import com.opencsv.CSVReader;
import com.opencsv.exceptions.CsvValidationException;
import java.io.FileReader;
import java.io.IOException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class Importer {
    private static final int THREAD_COUNT = 4; // Adjust based on performance testing
    private int skippedRowsCount = 0;

    public void importFeed(String filePath) {
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_COUNT);
        try (CSVReader reader = new CSVReader(new FileReader(filePath))) {
            String[] nextLine;
            while ((nextLine = reader.readNext()) != null) {
                executor.submit(() -> {
                    try {
                        processLine(nextLine);
                    } catch (MalformedInputException e) {
                        synchronized (this) {
                            reportSkippedRow(e.getReason());
                        }
                    }
                });
            }
        } catch (IOException | CsvValidationException e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
            try {
                executor.awaitTermination(1, TimeUnit.HOURS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void processLine(String[] line) throws MalformedInputException {
        // Implement logic to process each line and handle malformed inputs
        if (line.length < 5) {
            throw new MalformedInputException("Missing columns");
        }
        // Example: Check for blank quantities
        if (line[2].trim().isEmpty()) {
            throw new MalformedInputException("Blank quantity");
        }
        // Example: Check for currency symbols in prices
        if (line[3].matches(".*\\$.*")) {
            throw new MalformedInputException("Currency symbol in price");
        }
        // Additional processing logic...
    }

    private void reportSkippedRow(String reason) {
        skippedRowsCount++;
        System.out.println("Skipped row due to: " + reason);
    }

    public int getSkippedRowsCount() {
        return skippedRowsCount;
    }

    public static class MalformedInputException extends Exception {
        private final String reason;

        public MalformedInputException(String reason) {
            super(reason);
            this.reason = reason;
        }

        public String getReason() {
            return reason;
        }
    }
}
```

